-- Layer 0.2–0.5. Explicit conversions preserve old UTC event instants and Kabul business dates.
-- Calendar anchor rows generated by the verified shared Shamsi wrapper (1350–1499).
BEGIN;
SET LOCAL TIME ZONE 'UTC';
ALTER TABLE finance_journal DISABLE TRIGGER finance_journal_guard;
DROP TRIGGER finance_period_guard ON finance_period;
ALTER TABLE finance_journal DROP CONSTRAINT finance_journal_period_id_facility_id_fkey;
ALTER TABLE "finance_settings" ALTER COLUMN "cutover_date" TYPE timestamptz(3) USING "cutover_date"::timestamp AT TIME ZONE 'Asia/Kabul';
ALTER TABLE "finance_settings" ALTER COLUMN "created_at" TYPE timestamptz(3) USING "created_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "finance_account" ALTER COLUMN "created_at" TYPE timestamptz(3) USING "created_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "finance_period" ALTER COLUMN "starts_on" TYPE timestamptz(3) USING "starts_on"::timestamp AT TIME ZONE 'Asia/Kabul';
ALTER TABLE "finance_period" ALTER COLUMN "ends_on" TYPE timestamptz(3) USING "ends_on"::timestamp AT TIME ZONE 'Asia/Kabul';
ALTER TABLE "finance_period" ALTER COLUMN "closed_at" TYPE timestamptz(3) USING "closed_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "finance_journal" ALTER COLUMN "date" TYPE timestamptz(3) USING "date"::timestamp AT TIME ZONE 'Asia/Kabul';
ALTER TABLE "finance_journal" ALTER COLUMN "created_at" TYPE timestamptz(3) USING "created_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "finance_journal" ALTER COLUMN "posted_at" TYPE timestamptz(3) USING "posted_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "finance_supplier" ALTER COLUMN "created_at" TYPE timestamptz(3) USING "created_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "finance_bill" ALTER COLUMN "due_on" TYPE timestamptz(3) USING "due_on"::timestamp AT TIME ZONE 'Asia/Kabul';
ALTER TABLE "finance_statement" ALTER COLUMN "starts_on" TYPE timestamptz(3) USING "starts_on"::timestamp AT TIME ZONE 'Asia/Kabul';
ALTER TABLE "finance_statement" ALTER COLUMN "ends_on" TYPE timestamptz(3) USING "ends_on"::timestamp AT TIME ZONE 'Asia/Kabul';
ALTER TABLE "finance_statement" ALTER COLUMN "reconciled_at" TYPE timestamptz(3) USING "reconciled_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "finance_statement_line" ALTER COLUMN "date" TYPE timestamptz(3) USING "date"::timestamp AT TIME ZONE 'Asia/Kabul';
ALTER TABLE "audit_log" ALTER COLUMN "created_at" TYPE timestamptz(3) USING "created_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "drug" ALTER COLUMN "created_at" TYPE timestamptz(3) USING "created_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "drug" ALTER COLUMN "updated_at" TYPE timestamptz(3) USING "updated_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "integration_event" ALTER COLUMN "occurred_at" TYPE timestamptz(3) USING "occurred_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "integration_receipt" ALTER COLUMN "processed_at" TYPE timestamptz(3) USING "processed_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "command_receipt" ALTER COLUMN "created_at" TYPE timestamptz(3) USING "created_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "lab_test" ALTER COLUMN "created_at" TYPE timestamptz(3) USING "created_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "panel" ALTER COLUMN "created_at" TYPE timestamptz(3) USING "created_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "invoice" ALTER COLUMN "discount_approved_at" TYPE timestamptz(3) USING "discount_approved_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "invoice" ALTER COLUMN "created_at" TYPE timestamptz(3) USING "created_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "invoice" ALTER COLUMN "updated_at" TYPE timestamptz(3) USING "updated_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "invoice_item" ALTER COLUMN "paid_at" TYPE timestamptz(3) USING "paid_at"::timestamp AT TIME ZONE 'UTC';
ALTER TABLE "payment" ALTER COLUMN "received_at" TYPE timestamptz(3) USING "received_at"::timestamp AT TIME ZONE 'UTC';

-- Statement end remains an inclusive final instant; fiscal ends are exclusive.
ALTER TABLE finance_statement DISABLE TRIGGER finance_statement_guard;
UPDATE finance_statement SET ends_on = ends_on + interval '1 day' - interval '1 millisecond';
ALTER TABLE finance_statement ENABLE TRIGGER finance_statement_guard;
CREATE TABLE finance_legacy_period (
 id text PRIMARY KEY, facility_id text NOT NULL REFERENCES facility(id) ON DELETE RESTRICT ON UPDATE CASCADE,
 name text NOT NULL, starts_on timestamptz(3) NOT NULL, ends_on timestamptz(3) NOT NULL,
 closed_at timestamptz(3), closed_by text,
 CONSTRAINT finance_legacy_period_id_facility_id_key UNIQUE(id, facility_id)
);
INSERT INTO finance_legacy_period SELECT id, facility_id, name, starts_on, ends_on + interval '1 day', closed_at, closed_by FROM finance_period;
ALTER TABLE finance_journal ADD COLUMN legacy_period_id text;
UPDATE finance_journal SET legacy_period_id = period_id;
DELETE FROM finance_period;

CREATE TABLE fiscal_year (
 id text PRIMARY KEY, facility_id text NOT NULL REFERENCES facility(id) ON DELETE RESTRICT ON UPDATE CASCADE,
 year integer NOT NULL, label text NOT NULL,
 starts_on timestamptz(3) NOT NULL, ends_on timestamptz(3) NOT NULL,
 CONSTRAINT fiscal_year_facility_id_year_key UNIQUE(facility_id,year),
 CONSTRAINT fiscal_year_id_facility_id_key UNIQUE(id,facility_id),
 CONSTRAINT fiscal_year_dates CHECK(year BETWEEN 1350 AND 1499 AND label = year::text AND ends_on-starts_on IN (interval '365 days', interval '366 days'))
);
ALTER TABLE finance_period ADD COLUMN year_id text NOT NULL, ADD COLUMN month integer NOT NULL, ADD COLUMN label text NOT NULL;
ALTER TABLE finance_period ADD CONSTRAINT finance_period_year_id_facility_id_fkey FOREIGN KEY(year_id,facility_id) REFERENCES fiscal_year(id,facility_id) ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE UNIQUE INDEX finance_period_year_id_month_key ON finance_period(year_id,month);
CREATE UNIQUE INDEX finance_period_facility_id_label_key ON finance_period(facility_id,label);
CREATE TEMP TABLE fiscal_calendar_anchor(year integer, starts_on timestamptz, ends_on timestamptz) ON COMMIT DROP;
