-- Initialize 1404, current year, cutover year, and every year containing existing records.
INSERT INTO fiscal_year
SELECT gen_random_uuid()::text, s.facility_id, a.year, a.year::text, a.starts_on, a.ends_on
FROM finance_settings s CROSS JOIN fiscal_calendar_anchor a
WHERE a.year=1404 OR now() >= a.starts_on AND now() < a.ends_on
 OR s.cutover_date >= a.starts_on AND s.cutover_date < a.ends_on
 OR EXISTS (SELECT 1 FROM finance_legacy_period p WHERE p.facility_id=s.facility_id AND p.starts_on<a.ends_on AND p.ends_on>a.starts_on)
 OR EXISTS (SELECT 1 FROM finance_journal j WHERE j.facility_id=s.facility_id AND j.date>=a.starts_on AND j.date<a.ends_on);
INSERT INTO finance_period(id,facility_id,name,starts_on,ends_on,year_id,month,label)
SELECT gen_random_uuid()::text, y.facility_id,
 (ARRAY['Hamal','Sawr','Jawza','Saratan','Asad','Sunbula','Mizan','Aqrab','Qaws','Jadi','Dalwa','Hoot'])[m] || ' ' || y.label,
 y.starts_on + (CASE WHEN m<=6 THEN (m-1)*31 ELSE 186+(m-7)*30 END) * interval '1 day',
 CASE WHEN m=12 THEN y.ends_on ELSE y.starts_on+(CASE WHEN m<=6 THEN m*31 ELSE 186+(m-6)*30 END)*interval '1 day' END,
 y.id,m,y.label || '-' || lpad(m::text,2,'0')
FROM fiscal_year y CROSS JOIN generate_series(1,12) m;
UPDATE finance_journal j SET period_id=p.id FROM finance_period p
 WHERE j.facility_id=p.facility_id AND j.date>=p.starts_on AND j.date<p.ends_on;
ALTER TABLE finance_journal ADD CONSTRAINT finance_journal_period_id_facility_id_fkey FOREIGN KEY(period_id,facility_id) REFERENCES finance_period(id,facility_id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE finance_journal ADD CONSTRAINT finance_journal_legacy_period_id_facility_id_fkey FOREIGN KEY(legacy_period_id,facility_id) REFERENCES finance_legacy_period(id,facility_id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE finance_journal DROP CONSTRAINT finance_journal_reversal_of_id_fkey;
ALTER TABLE finance_journal ADD CONSTRAINT finance_journal_reversal_of_id_facility_id_fkey FOREIGN KEY(reversal_of_id,facility_id) REFERENCES finance_journal(id,facility_id) ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE UNIQUE INDEX finance_journal_reversal_of_id_facility_id_key ON finance_journal(reversal_of_id,facility_id);
CREATE TRIGGER finance_legacy_period_immutable BEFORE INSERT OR UPDATE OR DELETE ON finance_legacy_period FOR EACH ROW EXECUTE FUNCTION finance_immutable_source();
CREATE TRIGGER fiscal_year_immutable BEFORE UPDATE OR DELETE ON fiscal_year FOR EACH ROW EXECUTE FUNCTION finance_immutable_source();

CREATE OR REPLACE FUNCTION finance_guard_period() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE y fiscal_year; expected_start timestamptz; expected_end timestamptz;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Fiscal months cannot be deleted'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.closed_at IS NOT NULL THEN RAISE EXCEPTION 'Closed accounting periods are immutable'; END IF;
  IF (NEW.id,NEW.facility_id,NEW.year_id,NEW.month,NEW.label,NEW.name,NEW.starts_on,NEW.ends_on) IS DISTINCT FROM
     (OLD.id,OLD.facility_id,OLD.year_id,OLD.month,OLD.label,OLD.name,OLD.starts_on,OLD.ends_on) THEN RAISE EXCEPTION 'Fiscal month boundaries are immutable'; END IF;
 END IF;
 SELECT * INTO y FROM fiscal_year WHERE id=NEW.year_id AND facility_id=NEW.facility_id;
 IF NOT FOUND OR NEW.month NOT BETWEEN 1 AND 12 THEN RAISE EXCEPTION 'Invalid fiscal year or month'; END IF;
 expected_start := y.starts_on + (CASE WHEN NEW.month<=6 THEN (NEW.month-1)*31 ELSE 186+(NEW.month-7)*30 END)*interval '24 hours';
 expected_end := CASE WHEN NEW.month=12 THEN y.ends_on ELSE expected_start+(CASE WHEN NEW.month<=6 THEN 31 ELSE 30 END)*interval '24 hours' END;
 IF NEW.label<>y.label||'-'||lpad(NEW.month::text,2,'0') OR NEW.starts_on<>expected_start OR NEW.ends_on<>expected_end THEN RAISE EXCEPTION 'Fiscal month must use its canonical Shamsi boundaries'; END IF;
 IF NEW.closed_at IS NOT NULL THEN
  IF EXISTS (SELECT 1 FROM finance_journal WHERE period_id=NEW.id AND status='draft') THEN RAISE EXCEPTION 'Post or remove draft journals before closing'; END IF;
  IF EXISTS (SELECT 1 FROM integration_event e JOIN finance_settings s ON s.facility_id=e.facility_id
    WHERE e.facility_id=NEW.facility_id AND e.occurred_at>=GREATEST(NEW.starts_on,s.cutover_date) AND e.occurred_at<NEW.ends_on
    AND e.type IN ('hmis.Invoice.create.v1','hmis.Invoice.update.v1','hmis.Invoice.delete.v1','hmis.Payment.create.v1')
    AND NOT EXISTS (SELECT 1 FROM integration_receipt r WHERE r.event_id=e.id AND r.consumer='finance.ledger.v1'))
   THEN RAISE EXCEPTION 'Process outstanding hospital billing events before closing'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER finance_period_guard BEFORE INSERT OR UPDATE OR DELETE ON finance_period FOR EACH ROW EXECUTE FUNCTION finance_guard_period();
-- A year commits only with all twelve periods (including direct SQL callers).
CREATE FUNCTION finance_complete_year() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF (SELECT count(*) FROM finance_period WHERE year_id=NEW.id AND facility_id=NEW.facility_id)<>12 THEN RAISE EXCEPTION 'A fiscal year requires twelve periods'; END IF;
 RETURN NEW;
END $$;
CREATE CONSTRAINT TRIGGER fiscal_year_complete AFTER INSERT ON fiscal_year DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance_complete_year();
CREATE OR REPLACE FUNCTION finance_guard_journal() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE p finance_period; n integer; d numeric; c numeric;
BEGIN
  IF TG_OP <> 'INSERT' AND OLD.status = 'posted' THEN
    RAISE EXCEPTION 'Posted journals are immutable; create a reversal';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  SELECT * INTO p FROM finance_period WHERE id = NEW.period_id FOR UPDATE;
    IF p.id IS NULL OR p.closed_at IS NOT NULL OR NEW.date < p.starts_on OR NEW.date >= p.ends_on OR p.facility_id <> NEW.facility_id THEN
      RAISE EXCEPTION 'Posting requires the correct open accounting period';
    END IF;
  IF EXISTS (SELECT 1 FROM finance_legacy_period WHERE facility_id=NEW.facility_id AND closed_at IS NOT NULL AND starts_on<=NEW.date AND ends_on>NEW.date) THEN RAISE EXCEPTION 'Date is in a closed legacy period'; END IF;
  IF NOT EXISTS (SELECT 1 FROM finance_settings WHERE facility_id=NEW.facility_id AND cutover_date<=NEW.date) THEN RAISE EXCEPTION 'Date precedes finance cutover'; END IF;
  IF NEW.source_type='hospital' AND NOT EXISTS (SELECT 1 FROM integration_event WHERE id=NEW.source_id AND facility_id=NEW.facility_id) THEN RAISE EXCEPTION 'Hospital event must belong to journal facility'; END IF;
  IF NEW.status = 'posted' THEN
    SELECT COUNT(*), COALESCE(SUM(debit),0), COALESCE(SUM(credit),0) INTO n,d,c FROM finance_journal_line WHERE journal_id = NEW.id;
    IF n < 2 OR d <> c OR d <= 0 OR NEW.number IS NULL OR NEW.posted_at IS NULL OR NEW.posted_by IS NULL THEN
      RAISE EXCEPTION 'A posted journal must have balanced lines and posting metadata';
    END IF;
    IF EXISTS (SELECT 1 FROM finance_journal_line l JOIN finance_account a ON a.id=l.account_id WHERE l.journal_id=NEW.id AND NOT a.is_active) THEN
      RAISE EXCEPTION 'Cannot post to an inactive account';
    END IF;
    IF EXISTS (SELECT 1 FROM finance_journal_line l JOIN finance_statement s ON s.account_id=l.account_id WHERE l.journal_id=NEW.id AND s.reconciled_at IS NOT NULL AND s.ends_on >= NEW.date) THEN
      RAISE EXCEPTION 'Cannot backdate a cash transaction into a finalized reconciliation';
    END IF;
  END IF;
  RETURN NEW;
END $$;

ALTER TABLE finance_journal ENABLE TRIGGER finance_journal_guard;
