ALTER TABLE finance_legacy_period ADD CONSTRAINT finance_legacy_period_closed_by_facility_id_fkey FOREIGN KEY(closed_by,facility_id) REFERENCES app_user(id,facility_id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE finance_statement ADD CONSTRAINT finance_statement_reconciled_by_facility_id_fkey FOREIGN KEY(reconciled_by,facility_id) REFERENCES app_user(id,facility_id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE finance_journal_line ADD CONSTRAINT finance_journal_line_debit_finite CHECK (debit NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric));
ALTER TABLE finance_journal_line ADD CONSTRAINT finance_journal_line_credit_finite CHECK (credit NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric));
