ALTER TABLE finance_settlement ADD CONSTRAINT finance_settlement_amount_finite CHECK (amount NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric));
ALTER TABLE finance_statement ADD CONSTRAINT finance_statement_opening_balance_finite CHECK (opening_balance NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric));
ALTER TABLE finance_statement ADD CONSTRAINT finance_statement_closing_balance_finite CHECK (closing_balance NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric));
ALTER TABLE finance_statement_line ADD CONSTRAINT finance_statement_line_amount_finite CHECK (amount NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric));

