CREATE FUNCTION finance_guard_year() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE bounds record;
BEGIN
 SELECT * INTO bounds FROM fiscal_year_bounds(NEW.year);
 IF NOT FOUND OR NEW.starts_on<>bounds.starts_on OR NEW.ends_on<>bounds.ends_on THEN RAISE EXCEPTION 'Fiscal year must use verified Shamsi boundaries'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER fiscal_year_guard BEFORE INSERT ON fiscal_year FOR EACH ROW EXECUTE FUNCTION finance_guard_year();
COMMIT;
